1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export interface QuoteResult {
36	  premium: number;
37	}
38	
39	export interface ClaimResult {
40	  payout: number;
41	  remainingCap: number;
42	}
43	
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export interface ScenarioResult {
47	  results: StepResult[];
48	}
49	
50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	const BLOCK_SIZE = 3;
64	
65	const BLOCK_BASE_PREMIUM = 60;
66	
67	const countByType = (items: Item[]): Map<string, number> => {
68	  const counts = new Map<string, number>();
69	
70	  for (const item of items) {
71	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
72	  }
73	
74	  return counts;
75	};
76	
77	const typeGroupBasePremiumOf = ([type, count]: [string, number]): number =>
78	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
79	
80	const policyBasePremiumOf = (items: Item[]): number =>
81	  [...countByType(items)].reduce(
82	    (sum, typeGroup) => sum + typeGroupBasePremiumOf(typeGroup),
83	    0,
84	  );
85	
86	const HIGH_ENCHANTMENT_THRESHOLD = 5;
87	
88	// An item surcharge hits every item the predicate accepts, charging its rate
89	// against that item's own base premium.
90	interface ItemSurcharge {
91	  appliesTo: (item: Item) => boolean;
92	  rate: number;
93	}
94	
95	const ITEM_SURCHARGES: ItemSurcharge[] = [
96	  { appliesTo: (item) => item.cursed === true, rate: 0.5 },
97	  {
98	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
99	    rate: 0.3,
100	  },
101	];
102	
103	// One surcharge, totalled across every item it accepts.
104	const surchargeAcrossItems = (
105	  items: Item[],
106	  { appliesTo, rate }: ItemSurcharge,
107	): number =>
108	  items
109	    .filter(appliesTo)
110	    .reduce((sum, item) => sum + BASE_PREMIUMS[item.type] * rate, 0);
111	
112	// Item-specific surcharges apply to the affected item's own base premium.
113	const itemSurchargesOf = (items: Item[]): number =>
114	  ITEM_SURCHARGES.reduce(
115	    (sum, surcharge) => sum + surchargeAcrossItems(items, surcharge),
116	    0,
117	  );
118	
119	const LOYALTY_DISCOUNT_RATE = -0.2;
120	
121	const LOYALTY_YEARS_THRESHOLD = 2;
122	
123	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
124	
125	// The context a policy-wide modifier is judged against: who the customer is,
126	// and how many quotes they have already been given in this scenario.
127	interface PolicyContext {
128	  customer: Customer;
129	  precedingQuotes: number;
130	}
131	
132	// A policy modifier hits the whole policy when the predicate accepts it,
133	// charging its rate against the policy base premium. Discounts are negative
134	// rates, so surcharges and discounts sum uniformly.
135	interface PolicyModifier {
136	  appliesTo: (context: PolicyContext) => boolean;
137	  rate: number;
138	}
139	
140	const POLICY_MODIFIERS: PolicyModifier[] = [
141	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_RATE },
142	  {
143	    appliesTo: ({ customer }) =>
144	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
145	    rate: LOYALTY_DISCOUNT_RATE,
146	  },
147	  {
148	    appliesTo: ({ precedingQuotes }) => precedingQuotes >= 1,
149	    rate: FOLLOW_UP_DISCOUNT_RATE,
150	  },
151	];
152	
153	// Policy-wide modifiers apply to the policy base premium, so they are computed
154	// from the base alone — item-specific modifiers are not part of their base.
155	const policyModifiersOf = (policyBase: number, context: PolicyContext): number =>
156	  POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(context)).reduce(
157	    (sum, { rate }) => sum + policyBase * rate,
158	    0,
159	  );
160	
161	const quote = ({ items }: QuoteStep, context: PolicyContext): QuoteResult => {
162	  const policyBase = policyBasePremiumOf(items);
163	
164	  const premiumBeforeRounding =
165	    policyBase +
166	    itemSurchargesOf(items) +
167	    policyModifiersOf(policyBase, context) +
168	    PROCESSING_FEE;
169	
170	  return { premium: Math.ceil(premiumBeforeRounding) };
171	};
172	
173	const INSURANCE_VALUES: Record<string, number> = {
174	  sword: 1000,
175	  amulet: 600,
176	  staff: 800,
177	  potion: 400,
178	  rune: 250,
179	  moonstone: 250,
180	};
181	
182	const DEDUCTIBLE = 100;
183	
184	const CAP_MULTIPLE = 2;
185	
186	// A policy created by a quote step: what it covers, and how much of its
187	// payout cap is still available.
188	interface Policy {
189	  items: Item[];
190	  remainingCap: number;
191	}
192	
193	const policyFor = (items: Item[]): Policy => {
194	  const insuranceSum = items.reduce(
195	    (sum, item) => sum + INSURANCE_VALUES[item.type],
196	    0,
197	  );
198	
199	  return { items, remainingCap: CAP_MULTIPLE * insuranceSum };
200	};
201	
202	const HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
203	
204	const HALF_REIMBURSEMENT_RATE = 0.5;
205	
206	const FULL_REIMBURSEMENT_RATE = 1;
207	
208	// Damage to a highly enchanted item is reimbursed at half, before the
209	// deductible is taken off.
210	const reimbursementRateFor = (item: Item): number =>
211	  (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
212	    ? HALF_REIMBURSEMENT_RATE
213	    : FULL_REIMBURSEMENT_RATE;
214	
215	const payoutForDamage = (damage: Damage, damagedItem: Item): number =>
216	  damage.amount * reimbursementRateFor(damagedItem) - DEDUCTIBLE;
217	
218	// Settling a claim both reports a result and draws down the policy's cap, so
219	// it returns the policy as it stands afterwards rather than mutating in place.
220	interface Settlement {
221	  result: ClaimResult;
222	  policy: Policy;
223	}
224	
225	const damagedItemIn = (items: Item[], damage: Damage): Item =>
226	  items.find((item) => item.type === damage.itemType)!;
227	
228	const claim = ({ incident }: ClaimStep, policy: Policy): Settlement => {
229	  const desiredPayout = incident.damages.reduce(
230	    (sum, damage) =>
231	      sum + payoutForDamage(damage, damagedItemIn(policy.items, damage)),
232	    0,
233	  );
234	
235	  // The total payout per policy is capped, so a claim pays at most what the
236	  // policy has left.
237	  const payout = Math.min(desiredPayout, policy.remainingCap);
238	
239	  const remainingCap = policy.remainingCap - payout;
240	
241	  return {
242	    result: { payout: Math.floor(payout), remainingCap },
243	    policy: { ...policy, remainingCap },
244	  };
245	};
246	
247	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
248	  const results: StepResult[] = [];
249	
250	  const policies = new Map<number, Policy>();
251	
252	  let precedingQuotes = 0;
253	
254	  steps.forEach((step, index) => {
255	    if (step.op === "quote") {
256	      results.push(quote(step, { customer, precedingQuotes }));
257	      policies.set(index, policyFor(step.items));
258	      precedingQuotes += 1;
259	
260	      return;
261	    }
262	
263	    const { result, policy } = claim(step, policies.get(step.policy)!);
264	
265	    results.push(result);
266	    policies.set(step.policy, policy);
267	  });
268	
269	  return { results };
270	};
